package com.rikkeibank.customer.config; import com.rikkeibank.customer.model.Customer; import com.rikkeibank.customer.repository.CustomerRepository; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration public class DataInitializer{@Bean CommandLineRunner seed(CustomerRepository r){return a->{if(r.findByIdentityUsername("customer01").isEmpty()){Customer c=new Customer();c.setIdentityUsername("customer01");c.setFullName("Customer One");c.setEmail("customer01@rikkeibank.local");c.setPhone("0900000001");r.save(c);}};}}
